// reusable focus when the path must be passed around:
class Lens<S, A>(val get: (S) -> A, val set: (S, A) -> S) {
    fun <B> andThen(inner: Lens<A, B>) =
        Lens({ s -> inner.get(get(s)) }, { s, b -> set(s, inner.set(get(s), b)) })
}

