@optics data class Address(val city: String) { companion object }
@optics data class Person(val name: String, val home: Address) { companion object }

val city: Lens<Person, String> = Person.home.city   // plug-in dot syntax

city.get(p)                          // 'London'
city.set(p, "Berlin")
city.modify(p) { it.uppercase() }
